from __future__ import annotations

__doc__ = """Python wrapper layer for generated pure-Python libraries."""

from ..pywrapper_library import PyWrapperLibraryBase, WrapperBase


class PyWrapper(WrapperBase):
    """Wrapper for generated pure-python routines."""


class PyPyWrapperLibrary(PyWrapperLibraryBase):
    """Python wrapper library for generated pure-python libraries."""

    WRAPPER_CLASS = PyWrapper

    def resolve_wrapper_callable(self, libroutine_name, _libroutine):
        return getattr(self.wrapper_lib, libroutine_name)
